import random
from pipeline.stats import power_curve_clustered
rng = random.Random(1)
def pilot(rates, k=16):
    return {"c%03d"%i: {"family":"f%03d"%i,"split_group":"g%03d"%i,
            "scores":[1 if rng.random()<p else 0 for _ in range(k)]} for i,p in enumerate(rates)}
res = power_curve_clustered(pilot([1.0]*45+[0.0]*19), 16, mde=0.03, deltas=(0.05,0.08),
                            sizes=(300,), shapes=("concentrated",), trials=60, resamples=200, seed=7)
for r in res["rows"]:
    print("concentrated +%.0fpp N=%d power %.2f mean_lo %+.3f mean_delta %+.3f mean_effect %+.3f"
          % (r["delta"]*100, r["N"], r["power"], r["mean_lo"], r["mean_delta"], r["mean_effect"]))
